import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long target = nextLong();
        // |x-y| + |x+y| = 2 * max(|x|, |y|)
        if (target < 0 || target % 2 != 0) { System.out.println(0); return; }
        long radius = target / 2, le = 0, lt = 0;
        for (int i = 0; i < n; i++) {
            long x = Math.abs(nextLong());
            if (x <= radius) le++;
            if (x < radius) lt++;
        }
        System.out.println(le * (le - 1) / 2 - lt * (lt - 1) / 2);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, target := readInt(), readInt()
	// |x-y| + |x+y| = 2 * max(|x|, |y|)
	if target < 0 || target%2 != 0 {
		fmt.Println(0)
		return
	}
	radius, le, lt := target/2, 0, 0
	for i := 0; i < n; i++ {
		x := readInt()
		if x < 0 {
			x = -x
		}
		if x <= radius {
			le++
		}
		if x < radius {
			lt++
		}
	}
	fmt.Println(le*(le-1)/2 - lt*(lt-1)/2)
}
